window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-17387024b44d5d52"]={"versions": [{"id": "FIG-17387024b44d5d52", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm zur Paketformat- und Protokoll-Schichtung im AUTOSAR-Adaptive-Kommunikationsmanagement (<code>ara::com</code> / Communication Management). Es zeigt die schrittweise Kapselung und den Abdeckungsbereich von Sicherheits- (SecOC) und Transport-Headern (SOME/IP) bei der Übertragung serialisierter Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert ein Datenpaket in drei aufeinander aufbauende Stufen:</p>\n<ul class=\"fig-list\"><li><strong>SOME/IP Serialized Payload</strong>: Nutzdatenbereich, unterteilt in die Segmente oder Parameter <code>x</code>, <code>y</code> und <code>z</code>.\n</li><li><strong>SOME/IP Msg Header Part II</strong>: Zweiter Teil des SOME/IP-Nachrichten-Headers (enthält Request-ID / Client-ID &amp; Session-ID, Protocol Version, Interface Version, Message Type, Return Code), der der Serialized Payload direkt vorangestellt ist.\n</li><li><strong>SecOC (truncated) Freshness</strong>: An das Payload-Segment angehängter, gekürzter Frischewert zur Absicherung gegen Replay-Angriffe.\n</li><li><strong>SecOC (truncated) Authenticator</strong>: Angehängter, gekürzter Message Authentication Code (MAC) zur Integritäts- und Authentizitätsprüfung.\n</li><li><strong>SOME/IP Msg Header Part I</strong>: Erster Teil des SOME/IP-Nachrichten-Headers (Message ID bestehend aus Service ID und Method/Event ID sowie das SOME/IP-Längenfeld).\n</li><li><strong>Abdeckungsbereiche / Scopes</strong>:\n<ul class=\"fig-list\"><li><em>Payload covered by SecOC</em> (violett markiert): Umfasst <code>SOME/IP Msg Header Part II</code> und <code>SOME/IP Serialized Payload</code>.\n</li><li><em>Payload covered by SOME/IP Length</em> (blau markiert): Umfasst alle Bytes ab Beginn von <code>SOME/IP Msg Header Part II</code> über die serialisierte Payload bis einschließlich der beiden SecOC-Felder (Freshness und Authenticator).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm illustriert den Kapselungsablauf von oben nach unten:</p>\n<ol class=\"fig-list\"><li>Bereitstellung der serialisierten SOME/IP-Payload (<code>x</code>, <code>y</code>, <code>z</code>) zusammen mit dem nachgelagerten Header-Teil <code>SOME/IP Msg Header Part II</code>.\n</li><li>Berechnung des SecOC-Schutzes über genau diese Bytes (<code>SOME/IP Msg Header Part II</code> + <code>SOME/IP Serialized Payload</code>) und anschließendes Anhängen von <code>SecOC (truncated) Freshness</code> sowie <code>SecOC (truncated) Authenticator</code>.\n</li><li>Hinzufügen von <code>SOME/IP Msg Header Part I</code> am Paketanfang; das darin enthaltene SOME/IP-Längenfeld deckt alle nachfolgenden Bytes ab (<code>SOME/IP Msg Header Part II</code> + Payload + SecOC Freshness + SecOC Authenticator).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Protokoll-Layout und die Längenberechnung bei der Absicherung von SOME/IP-Nachrichten mittels SecOC:</p>\n<ul class=\"fig-list\"><li>Der kryptografische Authentifizierungsumfang von SecOC schließt <code>SOME/IP Msg Header Part II</code> sowie die serialisierte Payload ein, schließt jedoch <code>SOME/IP Msg Header Part I</code> und die SecOC-Erweiterungen selbst aus.\n</li><li>Das SOME/IP-Längenfeld in <code>SOME/IP Msg Header Part I</code> muss zwingend die Länge von <code>SOME/IP Msg Header Part II</code> (8 Bytes), der Nutzlast sowie der angehängten SecOC-Zusatzdaten (Freshness Value und MAC) summieren.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2f97f730eba7a635", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm zum Paket- und Headeraufbau im AUTOSAR-Adaptive-Kommunikationsmanagement (<code>ara::com</code> / Communication Management). Es stellt die Anordnung der Header- und Payload-Felder eines SOME/IP-Pakets mit angehängter SecOC-Absicherung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine lineare Paketstruktur bestehend aus folgenden Feldern:</p>\n<ul class=\"fig-list\"><li><strong>SOME/IP Msg Header Part I</strong>: Erster Abschnitt des SOME/IP-Headers (Message ID und Length-Feld).\n</li><li><strong>SOME/IP Msg Header Part II</strong>: Zweiter Abschnitt des SOME/IP-Headers (Request ID, Protocol Version, Interface Version, Message Type, Return Code).\n</li><li><strong>SOME/IP Serialized Payload</strong>: Nutzdatenfeld, unterteilt in die Komponenten <code>x</code>, <code>y</code> und <code>z</code>.\n</li><li><strong>SecOC (truncated) Freshness</strong>: Angehängter Frischewert zur Replay-Prävention.\n</li><li><strong>SecOC (truncated) Authenticator</strong>: Angehängter Prüfwert (MAC) zur Authentifizierung.\n</li><li><strong>Payload covered by SOME/IP Length</strong>: Oberhalb verlaufender Balken, der anzeigt, dass das SOME/IP-Längenfeld ab <code>SOME/IP Msg Header Part II</code> über die serialisierte Payload bis einschließlich des SecOC Authenticators reicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout des fertigen Transportpakets: <code>SOME/IP Msg Header Part I</code> führt das Paket an, gefolgt von <code>SOME/IP Msg Header Part II</code>, der serialisierten Payload (<code>x</code>, <code>y</code>, <code>z</code>) und den abschließenden SecOC-Feldern (Freshness und Authenticator). Das Längenfeld in Part I deckt alle nachfolgenden Felder lückenlos ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Nachrichtenlayout und die SOME/IP-Längenberechnung bei Einsatz von SecOC:</p>\n<ul class=\"fig-list\"><li>Die Gesamttransportlänge im SOME/IP-Header (Part I) umfasst die verbleibenden Header-Felder (Part II), die Nutzdaten sowie die vollständigen SecOC-Zusatzfelder (Freshness und Authenticator).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-89503668ed01de1e", "releases": ["R22-11", "R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm zum Paket- und Headeraufbau im AUTOSAR-Adaptive-Kommunikationsmanagement (<code>ara::com</code> / Communication Management). Es stellt die Anordnung der Header- und Payload-Felder eines SOME/IP-Pakets mit angehängter SecOC-Absicherung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine lineare Paketstruktur bestehend aus folgenden Feldern:</p>\n<ul class=\"fig-list\"><li><strong>SOME/IP Msg Header Part I</strong>: Erster Abschnitt des SOME/IP-Headers (Message ID und Length-Feld).\n</li><li><strong>SOME/IP Msg Header Part II</strong>: Zweiter Abschnitt des SOME/IP-Headers (Request ID, Protocol Version, Interface Version, Message Type, Return Code).\n</li><li><strong>SOME/IP Serialized Payload</strong>: Nutzdatenfeld, unterteilt in die Komponenten <code>x</code>, <code>y</code> und <code>z</code>.\n</li><li><strong>SecOC (truncated) Freshness</strong>: Angehängter Frischewert zur Replay-Prävention.\n</li><li><strong>SecOC (truncated) Authenticator</strong>: Angehängter Prüfwert (MAC) zur Authentifizierung.\n</li><li><strong>Payload covered by SOME/IP Length</strong>: Oberhalb verlaufender Balken, der anzeigt, dass das SOME/IP-Längenfeld ab <code>SOME/IP Msg Header Part II</code> über die serialisierte Payload bis einschließlich des SecOC Authenticators reicht.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Layout des fertigen Transportpakets: <code>SOME/IP Msg Header Part I</code> führt das Paket an, gefolgt von <code>SOME/IP Msg Header Part II</code>, der serialisierten Payload (<code>x</code>, <code>y</code>, <code>z</code>) und den abschließenden SecOC-Feldern (Freshness und Authenticator). Das Längenfeld in Part I deckt alle nachfolgenden Felder lückenlos ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Nachrichtenlayout und die SOME/IP-Längenberechnung bei Einsatz von SecOC:</p>\n<ul class=\"fig-list\"><li>Die Gesamttransportlänge im SOME/IP-Header (Part I) umfasst die verbleibenden Header-Felder (Part II), die Nutzdaten sowie die vollständigen SecOC-Zusatzfelder (Freshness und Authenticator).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-17387024b44d5d52", "to": "FIG-2f97f730eba7a635", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die schrittweise Darstellung des Protokollaufbaus in drei übereinanderliegenden Paketschichten entfällt; nur die finale Gesamtstruktur des SOME/IP-Pakets mit SecOC-Anhängen bleibt erhalten.\n</li><li>Die Beschriftung und Kennzeichnungsklammer „Payload covered by SecOC“ über dem Zwischenschritt entfällt.\n</li><li>Die vorangegangenen isolierten Teildarstellungen („SOME/IP Msg Header Part II“ mit „SOME/IP Serialized Payload [x, y, z]“ sowie die Variante mit angehängter Freshness und Authenticator) entfallen.\n</li><li>Die Beschriftung „Payload covered by SOME/IP Length“ ist am oberen Bildrand beschnitten.\n</li></ul>"}, {"from": "FIG-2f97f730eba7a635", "to": "FIG-89503668ed01de1e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
